import React from 'react';
import { Link } from 'react-router-dom';

const Navbar = () => {
  return (
    <nav style={{ background: '#222', color: 'white', padding: '0.75rem' }}>
      <ul style={{ listStyle: 'none', margin: 0, padding: 0 }}>
        <li style={{ display: 'inline', marginRight: '1rem' }}><Link to="/" style={{ color: 'white' }}>Inicio</Link></li>
        <li style={{ display: 'inline', marginRight: '1rem' }}><Link to="/content" style={{ color: 'white' }}>Ejercicios</Link></li>
        <li style={{ display: 'inline', marginRight: '1rem' }}><Link to="/login" style={{ color: 'white' }}>Iniciar sesión</Link></li>
        <li style={{ display: 'inline' }}><Link to="/register" style={{ color: 'white' }}>Registro</Link></li>
      </ul>
    </nav>
  );
};

export default Navbar;
